/* Token Radar — dark board. Palette: ink canvas, amber signal, teal growth. */
:root {
  --canvas: #0e151c;
  --surface: #16222d;
  --surface-2: #1d2c3a;
  --ink: #e8eef2;
  --muted: #93a5b1;
  --border: #2a3a47;
  --accent: #f5b301;
  --teal: #2dd4bf;
  --positive: #34d399;
  --negative: #f87171;
  --radius: 12px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, monospace;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body { margin: 0; background: var(--canvas); color: var(--ink); font: 400 15px/1.55 var(--font-body); }
h1, h2, h3 { margin: 0; letter-spacing: -.02em; }
h1 { font-size: 30px; line-height: 1.15; }
h2 { font-size: 19px; }
h3 { font-size: 15px; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.skip { position: absolute; left: -9999px; top: 0; padding: 8px 16px; background: var(--surface); border: 1px solid var(--border); z-index: 20; }
.skip:focus { left: 16px; top: 16px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.shell { max-width: 1340px; margin: 0 auto; padding: 28px 32px 56px; }
.top { display: flex; justify-content: space-between; gap: 24px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.brand { display: flex; align-items: center; gap: 10px; }
.mark { width: 12px; height: 12px; border-radius: 3px; background: var(--accent); transform: rotate(45deg); flex: none; }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: .04em; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: 12px; justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.hero { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(280px, .6fr); gap: 32px; padding: 32px 0 24px; }
.hero p { color: var(--muted); max-width: 64ch; margin-top: 8px; }
.hero p b { color: var(--ink); }
.kpis { display: grid; gap: 8px; align-content: start; border-left: 1px solid var(--border); padding-left: 24px; }
.kpi { display: flex; justify-content: space-between; gap: 12px; }
.kpi b { font-family: var(--font-num); font-size: 15px; font-weight: 600; color: var(--accent); }
.kpi span { color: var(--muted); font-size: 13px; }
.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
.sandbox { margin-bottom: 16px; padding: 20px; display: grid; gap: 12px; }
.sandbox h2 { font-size: 16px; }
.sandbox .sub { color: var(--muted); font-size: 13px; }
.sliders { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.slider { display: grid; gap: 4px; font-size: 13px; color: var(--muted); }
.slider output { font-family: var(--font-num); color: var(--ink); }
.slider input { width: 100%; accent-color: var(--accent); }
.sandbox-result { font-family: var(--font-num); font-size: 13px; color: var(--teal); }
.controls { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; padding: 16px 0; }
.field { display: grid; gap: 4px; }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select { min-height: 36px; padding: 0 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); min-width: 170px; }
.field input { min-width: 260px; }
.check { display: flex; align-items: center; gap: 8px; min-height: 36px; color: var(--muted); font-size: 13px; }
.check input { accent-color: var(--accent); width: 16px; height: 16px; }
.tabs { display: flex; gap: 4px; padding: 3px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.tabs button { min-height: 30px; padding: 0 12px; border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: #14100a; font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: 12px; border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
th { color: var(--muted); font-size: 12px; font-weight: 500; white-space: nowrap; }
th button { display: inline-flex; gap: 4px; border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--surface-2); }
tbody tr[data-selected="true"] { background: #22384a; }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--positive); }
.neg { color: var(--negative); }
.bar { width: 110px; height: 6px; border-radius: 3px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: 8px; }
.badge { display: inline-flex; gap: 6px; align-items: center; color: var(--muted); font-size: 12px; white-space: nowrap; }
.badge::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--teal); }
.badge.live::before { background: var(--accent); }
.watch { color: var(--accent); font-size: 11px; font-family: var(--font-num); }
.model { margin-top: 16px; padding: 20px; display: grid; gap: 12px; }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.7; color: var(--muted); overflow-wrap: anywhere; }
.empty { padding: 56px 20px; text-align: center; display: grid; gap: 12px; justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 36px; padding: 0 16px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.button.primary { background: var(--accent); border-color: var(--accent); color: #14100a; font-weight: 600; }
.detail { position: fixed; top: 0; right: 0; bottom: 0; width: min(540px, 94vw); z-index: 10; background: var(--surface); border-left: 1px solid var(--border); padding: 20px; overflow-y: auto; margin: 0 0 0 auto; max-height: 100%; color: var(--ink); }
.detail::backdrop { background: rgba(5, 10, 14, .6); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: 16px; }
.close { flex: none; min-width: 32px; min-height: 32px; padding: 0 8px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.detail h2 { margin-top: 4px; }
.detail .sub { margin-top: 4px; }
.detail-section { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: 8px; }
.equation { display: grid; gap: 8px; font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: 12px; }
.equation span { color: var(--muted); }
.steps { margin: 0; padding-left: 20px; display: grid; gap: 12px; }
.steps li { padding-left: 4px; }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }
.note { margin-top: 16px; padding: 20px; color: var(--muted); font-size: 13px; display: grid; gap: 8px; }
.note b { color: var(--ink); }
@media (max-width: 900px) {
  .shell { padding: 16px; }
  .hero { grid-template-columns: 1fr; gap: 16px; }
  .kpis { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: 16px; }
  .sliders { grid-template-columns: 1fr; }
  .field input { min-width: 0; width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; }
}
